     * $query->filterByFechaCreacion('fooValue');   // WHERE FECHA_CREACION = 'fooValue'
     * $query->filterByFechaCreacion('%fooValue%'); // WHERE FECHA_CREACION LIKE '%fooValue%'
     * </code>
     *
     * @param     string $fechaCreacion The value to use as filter.
     *              Accepts wildcards (* and % trigger a LIKE)
     * @param     string $comparison Operator to use for the column comparison, defaults to Criteria::EQUAL
     *
     * @return BpmnProcessMetricsQuery The current query, for fluid interface
     */
    public function filterByFechaCreacion($fechaCreacion = null, $comparison = null)
    {
        if (null === $comparison) {
            if (is_array($fechaCreacion)) {
                $comparison = Criteria::IN;
            } elseif (preg_match('/[\%\*]/', $fechaCreacion)) {
                $fechaCreacion = str_replace('*', '%', $fechaCreacion);
                $comparison = Criteria::LIKE;
            }
        }

        return $this->addUsingAlias(BpmnProcessMetricsPeer::FECHA_CREACION, $fechaCreacion, $comparison);
    }

